import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.EnabledVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.GrantTypesJsonVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.IntrospectionAllowedVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.RequirePkceVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.RequirePushedAuthorizationRequestsVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.ResponseTypesJsonVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.SubjectTypeVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.TenantVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.TlsClientCertificateBoundAccessTokensVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.TokenEndpointAuthMethodVO;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.UidVO;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;

/**
 * Tenant rule and registered policy of the clients (tasks 0.4 and 0.5).
 */
class OauthClientPolicyUnitTest {

  private static final String TENANT_A = "tenant-a-uid";
  private static final String TENANT_B = "tenant-b-uid";

  private static OauthClient.OauthClientBuilder client(String uid, String tenantUid) {
    return OauthClient.builder().uidValue(UidVO.from(uid)).codeValue(CodeVO.from("app"))
        .tenantValue(tenantUid == null ? TenantVO.nullValue() : TenantVO.fromReference(tenantUid))
        .tokenEndpointAuthMethodValue(TokenEndpointAuthMethodVO
            .from(OauthClientTokenEndpointAuthMethodOptions.CLIENT_SECRET_BASIC))
        .dpopBoundAccessTokensValue(DpopBoundAccessTokensVO.from(false))
        .tlsClientCertificateBoundAccessTokensValue(
            TlsClientCertificateBoundAccessTokensVO.from(false))
        .subjectTypeValue(SubjectTypeVO.from(OauthClientSubjectTypeOptions.PUBLIC))
        .allowedLoginRedirectsValue(AllowedLoginRedirectsVO.from(List.<AllowedLoginRedirects>of()))
        .allowedLogoutRedirectsValue(AllowedLogoutRedirectsVO.from(List.of()))
        .allowedAudiencesValue(AllowedAudiencesVO.from(List.<AllowedAudiences>of()))
        .introspectionAllowedValue(IntrospectionAllowedVO.from(false))
        .requirePushedAuthorizationRequestsValue(RequirePushedAuthorizationRequestsVO.from(false))
        .requirePkceValue(RequirePkceVO.from(false)).enabledValue(EnabledVO.from(true))
        .clientCredentialsTokenTtlSecondsValue(ClientCredentialsTokenTtlSecondsVO.from(3600));
  }

  @Test
  @DisplayName("The tenant's own client wins over a global one with the same code")
  void own_client_wins_over_global() {
    OauthClient global = client("global", null).build();
    OauthClient own = client("own", TENANT_A).build();
    Assertions.assertEquals("own",
        OauthClientPolicy.select(List.of(global, own), TENANT_A).orElseThrow().getUid());
  }

  @Test
  @DisplayName("A global client is visible from every tenant")
  void global_client_visible_everywhere() {
    OauthClient global = client("global", null).build();
    Assertions.assertTrue(OauthClientPolicy.select(List.of(global), TENANT_A).isPresent());
    Assertions.assertTrue(OauthClientPolicy.select(List.of(global), TENANT_B).isPresent());
    Assertions.assertTrue(OauthClientPolicy.visibleFrom(global, TENANT_B));
  }

  @Test
  @DisplayName("A client of tenant A is never returned in tenant B")
  void client_of_other_tenant_never_returned() {
    OauthClient ofA = client("of-a", TENANT_A).build();
    Assertions.assertEquals(Optional.empty(), OauthClientPolicy.select(List.of(ofA), TENANT_B));
    Assertions.assertFalse(OauthClientPolicy.visibleFrom(ofA, TENANT_B));
  }

  @Test
  @DisplayName("Without registered grants the default is code + refresh, never password")
  void default_grants_exclude_password() {
    ClientDetails details = OauthClientPolicy.details(client("c", TENANT_A).build(), List.of())
        .protectedWithSecret(true).build();
    Assertions.assertTrue(details.allowedGrant("authorization_code"));
    Assertions.assertTrue(details.allowedGrant("refresh_token"));
    Assertions.assertFalse(details.allowedGrant("password"));
    Assertions.assertFalse(details.allowedGrant("mfa"));
    Assertions.assertFalse(details.allowedGrant("client_credentials"));
    Assertions.assertEquals(List.of("code"), details.getAllowedResponseTypes());
  }

  @Test
  @DisplayName("Registered grants, response types and M2M scopes are applied")
  void registered_configuration_is_applied() {
    OauthClient app = client("c", TENANT_A)
        .grantTypesJsonValue(GrantTypesJsonVO.from("[\"client_credentials\",\"password\"]"))
        .responseTypesJsonValue(ResponseTypesJsonVO.from("[]"))
        .clientCredentialsScopesValue(ClientCredentialsScopesVO.from("orders:read orders:write"))
        .build();
    ClientDetails details = OauthClientPolicy.details(app, List.of()).build();
    Assertions.assertTrue(details.allowedGrant("client_credentials"));
    Assertions.assertTrue(details.allowedGrant("password"));
    Assertions.assertTrue(details.allowedGrant("mfa"));
    Assertions.assertFalse(details.allowedGrant("authorization_code"));
    Assertions.assertFalse(details.allowsResponseType("code"));
    Assertions.assertEquals(List.of("orders:read", "orders:write"),
        details.getClientCredentialsScopes());
  }

  @Test
  @DisplayName("Without allowAllScopes a client only gets the standard OIDC scopes in user flows")
  void user_scopes_follow_allow_all_scopes() {
    ClientDetails limited = OauthClientPolicy
        .details(client("c", TENANT_A).allowAllScopesValue(AllowAllScopesVO.from(false)).build(),
            List.of())
        .build();
    Assertions.assertEquals(List.of("openid", "profile"),
        limited.grantableScopes(List.of("openid", "admin", "profile")));
    ClientDetails all = OauthClientPolicy
        .details(client("c", TENANT_A).allowAllScopesValue(AllowAllScopesVO.from(true)).build(),
            List.of())
        .build();
    Assertions.assertEquals(List.of("openid", "admin"),
        all.grantableScopes(List.of("openid", "admin")));
  }

  @Test
  @DisplayName("Registered lists are read as JSON arrays or as separated values")
  void parse_list_formats() {
    Assertions.assertEquals(Optional.of(List.of("a", "b")),
        OauthClientPolicy.parseList("[\"a\", \"b\"]"));
    Assertions.assertEquals(Optional.of(List.of("a", "b")), OauthClientPolicy.parseList("a, b a"));
    Assertions.assertEquals(Optional.empty(), OauthClientPolicy.parseList(" "));
    Assertions.assertEquals(Optional.empty(), OauthClientPolicy.parseList("[]"));
    Assertions.assertEquals(Optional.empty(), OauthClientPolicy.parseList("[broken"));
  }
}
